{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a highly lipophilic long-chain fatty acid ester prodrug, had an absolute oral bioavailability of only 6.83 ± 3.32% in young women, showing that this lipophilic ester class is poorly systemically available after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate steroid ester, showed poor and inconsistent oral bioavailability in men, reinforcing the low oral absorption expected for highly lipophilic ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Testosterone undecanoate in crystalline form had poor oral bioavailability in patients, consistent with the very low systemic exposure of lipophilic, poorly water-soluble ester compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Colesevelam, a non-absorbed polymer designed for local gastrointestinal action, had negligible systemic bioavailability, illustrating that locally acting GI drugs can have extremely low oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic beta-lactone lipase inhibitor intended for local gastrointestinal action; it is minimally absorbed, and analogous long-chain lipophilic ester prodrugs show low oral bioavailability, so F is well below the 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability record for orlistat itself is present in the evidence set.",
    "Closest structural analogs are long-chain fatty acid esters, not beta-lactone lipase inhibitors; direct quantitative F for orlistat is unavailable in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

